#!/usr/bin/env bash
# AKFC — Page « S'inscrire » : le texte affiché était figé dans le code (tant que la page n'avait
# aucun bloc), d'où un éditeur vide. Désormais :
#  - au démarrage, la page reçoit son texte de départ comme VRAI bloc de texte, modifiable dans
#    Pages éditoriales → S'inscrire (créée si absente, ou remplie si elle existe sans aucun bloc ;
#    jamais réécrite ensuite) ;
#  - la page publique affiche exactement le contenu du constructeur (plus de texte figé),
#    suivi des « Liens utiles » des partenaires.
#  Le badge « Brouillon » = page pas encore PUBLIÉE (sans rapport avec son contenu).
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash fix-inscription-editable.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
SVC="packages/backend/src/modules/sitePages/ensureInscriptionPage.service.ts"
[ -f "$SVC" ] && { echo "— déjà appliqué"; exit 0; }
FILES=("apps/web/src/app/(public)/inscription/page.tsx" apps/web/src/instrumentation.ts)
grep -q "Vous souhaitez vous inscrire" "apps/web/src/app/(public)/contacts/page.tsx" || { echo "ERREUR: applique d'abord fix-inscription-placement.sh." >&2; exit 1; }
BK=/tmp/akfc_ie_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
restore(){ for f in "${FILES[@]}"; do cp "$BK/$f" "$f"; done; rm -f "$SVC"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }
W=/tmp/akfc_ie; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"
echo "== application =="
mkdir -p "$(dirname "$SVC")"
echo '' | base64 -d > "$SVC" && echo "  ok  $SVC"
python3 "$W/edit.py" . || { restore; exit 1; }
if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi
echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"
git add "$SVC" "${FILES[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
fix(inscription): texte de départ modifiable dans le constructeur (plus de texte figé)

